\documentclass[border=5pt]{standalone}
\usepackage{tikz}
\usepackage{bytefield}
\usepackage{fontspec}
\setmainfont{FiraMono-Regular}
\tikzset{
    bytefield/box/.style={draw, line width=1pt},
}
\begin{document}
\begin{bytefield}[bitformatting=\small,bitheight=2\baselineskip,bitwidth=0.04\textwidth]{32}
\bitheader{0-31} \\
\bitbox{4}{Version} \bitbox{4}{IHL} \bitbox{8}{Type of service} \bitbox{16}{Total length} \\
\bitbox{16}{Identification} 
\bitbox{1}{}\bitbox{1}{D\\F} \bitbox{1}{M\\F} 
\bitbox{13}{Fragment offset} \\
\bitbox{8}{Time to live} \bitbox{8}{Protocol} \bitbox{16}{Header checksum} \\
\bitbox{32}{Source IP address} \\
\bitbox{32}{Destination IP address} \\
\bitbox{32}{Options (0-10 words)} \\
\end{bytefield}
\end{document}
